/** A labelled form group, the way Flarum's own forms lay them out. */
export default function Field(label, control, help, id) {
  return m("div", {
    className: "Form-group"
  }, m("label", {
    for: id
  }, label), control, help ? m("div", {
    className: "helpText"
  }, help) : null);
}
flarum.reg.add('ernestdefoe-syllabus', 'forum/components/Field', Field);